mapper.select:
SELECT

FROM memory_stores

    workspace_uuid = #{params.WorkspaceUUID}
    AND deleted_at IS NULL

        AND archived_at IS NULL


        AND created_at >= #{params.CreatedAtGTE}


        AND created_at <= #{params.CreatedAtLTE}


        AND (
            created_at < #{params.CursorCreatedAt}
            OR (created_at = #{params.CursorCreatedAt} AND uuid < #{params.CursorUUID})
        )


ORDER BY created_at DESC, uuid DESC
LIMIT #{params.Limit}

SELECT EXISTS (
    SELECT 1
    FROM memory_stores
    WHERE workspace_uuid = #{workspaceUUID}
    AND external_id = #{externalID}
    AND deleted_at IS NULL
)
